// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {Vm} from "forge-std/Vm.sol";
import {strings} from "solidity-stringutils/src/strings.sol";

import {Options, DefenderOptions} from "../Options.sol";
import {ProposeUpgradeResponse, ApprovalProcessResponse} from "../Defender.sol";
import {ContractInfo, Utils} from "./Utils.sol";
import {Versions} from "./Versions.sol";

/**
 * @dev Internal library for deploying contracts and proposing upgrades using OpenZeppelin Defender.
 */
library DefenderDeploy {
    using strings for *;

    /**
     * @notice Deploys a contract using the provided contract name, constructor data, and deployment options.
     *
     * @param contractName The name of the contract to be deployed.
     * @param constructorData The encoded constructor arguments for the contract.
     * @param defenderOpts The deployment options, including any specific configurations for the Defender service.
     *
     * @return The address of the deployed contract.
     */
    function deploy(
        string memory contractName,
        bytes memory constructorData,
        DefenderOptions memory defenderOpts
    ) internal returns (address) {
        string memory outDir = Utils.getOutDir();
        ContractInfo memory contractInfo = Utils.getContractInfo(contractName, outDir);
        string memory buildInfoFile = Utils.getBuildInfoFile(contractInfo.sourceCodeHash, contractName, outDir);

        string[] memory inputs = buildDeployCommand(contractInfo, buildInfoFile, constructorData, defenderOpts);
        Vm.FfiResult memory result = Utils.runAsBashCommand(inputs);

        if (result.exitCode != 0) {
            revert(
                string(
                    abi.encodePacked(
                        "Failed to deploy contract ",
                        contractName,
                        " using Defender: ",
                        string(result.stderr)
                    )
                )
            );
        }

        string memory stdout = string(result.stdout);
        return _parseDeployedAddress(stdout);
    }

    /**
     * @notice Constructs a deploy command for deploying a contract using OpenZeppelin Defender.
     *
     * @param contractInfo Contains details about the contract, such as its name, path, and license.
     * @param buildInfoFile The file containing build information for the contract.
     * @param constructorData Bytecode for the contract's constructor, if any.
     * @param defenderOpts Configuration options for the Defender deployment.
     *
     * @return inputs The array of strings representing the deploy command.
     */
    function buildDeployCommand(
        ContractInfo memory contractInfo,
        string memory buildInfoFile,
        bytes memory constructorData,
        DefenderOptions memory defenderOpts
    ) internal view returns (string[] memory) {
        Vm vm = Vm(Utils.CHEATCODE_ADDRESS);

        if (bytes(defenderOpts.licenseType).length > 0 && defenderOpts.skipVerifySourceCode) {
            revert("Cannot set licenseType when skipVerifySourceCode is true");
        }
        if (bytes(defenderOpts.licenseType).length > 0 && defenderOpts.skipLicenseType) {
            revert("Cannot set licenseType when skipLicenseType is true");
        }

        string[] memory inputBuilder = new string[](255);
        uint256 i = 0;

        inputBuilder[i++] = "npx";
        inputBuilder[i++] = string(
            abi.encodePacked("@openzeppelin/defender-deploy-client-cli@", Versions.DEFENDER_DEPLOY_CLIENT_CLI)
        );
        inputBuilder[i++] = "deploy";
        inputBuilder[i++] = "--contractName";
        inputBuilder[i++] = contractInfo.shortName;
        inputBuilder[i++] = "--contractPath";
        inputBuilder[i++] = contractInfo.contractPath;
        inputBuilder[i++] = "--chainId";
        inputBuilder[i++] = vm.toString(block.chainid);
        inputBuilder[i++] = "--buildInfoFile";
        inputBuilder[i++] = buildInfoFile;

        if (constructorData.length > 0) {
            inputBuilder[i++] = "--constructorBytecode";
            inputBuilder[i++] = vm.toString(constructorData);
        }

        if (!defenderOpts.skipVerifySourceCode) {
            if (defenderOpts.skipLicenseType) {
                inputBuilder[i++] = "--skipLicenseType";
            } else if (bytes(defenderOpts.licenseType).length > 0) {
                inputBuilder[i++] = "--licenseType";
                inputBuilder[i++] = defenderOpts.licenseType;
            } else {
                string memory licenseType = _toLicenseType(contractInfo);
                if (bytes(licenseType).length > 0) {
                    inputBuilder[i++] = "--licenseType";
                    inputBuilder[i++] = licenseType;
                }
            }
        } else {
            inputBuilder[i++] = "--skipVerifySourceCode";
        }

        if (bytes(defenderOpts.relayerId).length > 0) {
            inputBuilder[i++] = "--relayerId";
            inputBuilder[i++] = defenderOpts.relayerId;
        }

        if (defenderOpts.salt != bytes32(0)) {
            inputBuilder[i++] = "--salt";
            inputBuilder[i++] = vm.toString(defenderOpts.salt);
        }

        if (defenderOpts.txOverrides.gasLimit > 0) {
            inputBuilder[i++] = "--gasLimit";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.gasLimit);
        }

        if (defenderOpts.txOverrides.gasPrice > 0) {
            inputBuilder[i++] = "--gasPrice";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.gasPrice);
        }

        if (defenderOpts.txOverrides.maxFeePerGas > 0) {
            inputBuilder[i++] = "--maxFeePerGas";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.maxFeePerGas);
        }

        if (defenderOpts.txOverrides.maxPriorityFeePerGas > 0) {
            inputBuilder[i++] = "--maxPriorityFeePerGas";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.maxPriorityFeePerGas);
        }

        if (bytes(defenderOpts.metadata).length > 0) {
            inputBuilder[i++] = "--metadata";
            inputBuilder[i++] = defenderOpts.metadata;
        }

        string[] memory inputs = new string[](i);
        for (uint256 j = 0; j < i; j++) {
            inputs[j] = inputBuilder[j];
        }

        return inputs;
    }

    /**
     * @notice Converts a given SPDX license identifier into a standardized license type.
     *
     * @param contractInfo A struct containing the license identifier and contract path.
     * @return string memory The standardized license type corresponding to the SPDX identifier.
     */
    function _toLicenseType(ContractInfo memory contractInfo) private pure returns (string memory) {
        string memory license = contractInfo.license;
        strings.slice memory licenseSlice = license.toSlice();

        if (licenseSlice.equals("MIT".toSlice())) {
            return "MIT";
        } else if (licenseSlice.equals("Apache-2.0".toSlice())) {
            return "Apache-2.0";
        } else if (licenseSlice.equals("GPL-2.0".toSlice())) {
            return "GPL-2.0";
        } else if (licenseSlice.equals("GPL-2.0-only".toSlice())) {
            return "GPL-2.0-only";
        } else if (licenseSlice.equals("GPL-2.0-or-later".toSlice())) {
            return "GPL-2.0-or-later";
        } else if (licenseSlice.equals("GPL-3.0".toSlice())) {
            return "GPL-3.0";
        } else if (licenseSlice.equals("GPL-3.0-only".toSlice())) {
            return "GPL-3.0-only";
        } else if (licenseSlice.equals("GPL-3.0-or-later".toSlice())) {
            return "GPL-3.0-or-later";
        } else if (licenseSlice.equals("LGPL-2.1".toSlice())) {
            return "LGPL-2.1";
        } else if (licenseSlice.equals("LGPL-2.1-only".toSlice())) {
            return "LGPL-2.1-only";
        } else if (licenseSlice.equals("LGPL-2.1-or-later".toSlice())) {
            return "LGPL-2.1-or-later";
        } else if (licenseSlice.equals("LGPL-3.0".toSlice())) {
            return "LGPL-3.0";
        } else if (licenseSlice.equals("LGPL-3.0-only".toSlice())) {
            return "LGPL-3.0-only";
        } else if (licenseSlice.equals("LGPL-3.0-or-later".toSlice())) {
            return "LGPL-3.0-or-later";
        } else if (licenseSlice.equals("BSD-2-Clause".toSlice())) {
            return "BSD-2-Clause";
        } else if (licenseSlice.equals("BSD-3-Clause".toSlice())) {
            return "BSD-3-Clause";
        } else if (licenseSlice.equals("MPL-2.0".toSlice())) {
            return "MPL-2.0";
        } else if (licenseSlice.equals("BSL-1.1".toSlice())) {
            return "BSL-1.1";
        } else if (licenseSlice.equals("Unlicense".toSlice())) {
            return "Unlicense";
        } else if (licenseSlice.equals("CC0-1.0".toSlice())) {
            return "CC0-1.0";
        } else if (licenseSlice.equals("AGPL-3.0".toSlice())) {
            return "AGPL-3.0";
        } else if (licenseSlice.equals("AGPL-3.0-only".toSlice())) {
            return "AGPL-3.0-only";
        } else if (licenseSlice.equals("AGPL-3.0-or-later".toSlice())) {
            return "AGPL-3.0-or-later";
        } else if (bytes(license).length == 0) {
            return "";
        } else {
            revert(
                string(
                    abi.encodePacked(
                        "Unsupported SPDX license identifier: ",
                        license,
                        " in contract ",
                        contractInfo.contractPath,
                        ". Use the `licenseType` option to specify the license type manually."
                    )
                )
            );
        }
    }

    /**
     * @notice Proposes an upgrade for a proxy contract by deploying a new implementation and submitting the upgrade proposal.
     *
     * @param proxyAddress The address of the proxy contract to be upgraded.
     * @param proxyAdminAddress The address of the proxy admin contract that manages the proxy.
     * @param newImplementationAddress The address of the new implementation contract.
     * @param newImplementationContractName The name of the new implementation contract.
     * @param opts Additional options for the upgrade proposal.
     *
     * @return ProposeUpgradeResponse A struct containing the response from the upgrade proposal process.
     */
    function proposeUpgrade(
        address proxyAddress,
        address proxyAdminAddress,
        address newImplementationAddress,
        string memory newImplementationContractName,
        Options memory opts
    ) internal returns (ProposeUpgradeResponse memory) {
        string memory outDir = Utils.getOutDir();
        ContractInfo memory contractInfo = Utils.getContractInfo(newImplementationContractName, outDir);

        string[] memory inputs = buildProposeUpgradeCommand(
            proxyAddress,
            proxyAdminAddress,
            newImplementationAddress,
            contractInfo,
            opts
        );
        Vm.FfiResult memory result = Utils.runAsBashCommand(inputs);

        if (result.exitCode != 0) {
            revert(
                string(
                    abi.encodePacked(
                        "Failed to propose upgrade: ",
                        string(result.stderr)
                    )
                )
            );
        }

        string memory stdout = string(result.stdout);
        return parseProposeUpgradeResponse(stdout);
    }

    /**
     * @notice Parses the response from a propose upgrade command and extracts the proposal ID and URL.
     *
     * @param stdout The raw string output from the propose upgrade command.
     * @return response A `ProposeUpgradeResponse` struct containing the parsed proposal ID and URL.
     */
    function parseProposeUpgradeResponse(string memory stdout) internal pure returns (ProposeUpgradeResponse memory) {
        ProposeUpgradeResponse memory response;
        response.proposalId = _parseLine("Proposal ID: ", stdout, true);
        response.url = _parseLine("Proposal URL: ", stdout, true);
        return response;
    }

    /**
     * @notice Parses a line from a given string output based on an expected prefix.
     *
     * @param expectedPrefix The prefix to search for in the output string.
     * @param stdout The output string to parse.
     * @param required Whether the line with the prefix is mandatory.
     * @return The parsed line or an empty string if not required.
     */
    function _parseLine(
        string memory expectedPrefix,
        string memory stdout,
        bool required
    ) private pure returns (string memory) {
        strings.slice memory outputSlice = stdout.toSlice();
        strings.slice memory prefixSlice = expectedPrefix.toSlice();

        if (outputSlice.contains(prefixSlice)) {
            strings.slice memory remaining = outputSlice.copy();
            remaining.split(prefixSlice);
            string memory afterPrefix = remaining.toString();
            strings.slice memory afterPrefixSlice = afterPrefix.toSlice();
            string memory result = afterPrefixSlice.split("\n".toSlice()).toString();
            return result;
        } else if (required) {
            revert(
                string(abi.encodePacked("Expected prefix not found in output: ", expectedPrefix))
            );
        } else {
            return "";
        }
    }

    /**
     * @notice Builds a command to propose an upgrade for a proxy contract using OpenZeppelin Defender.
     *
     * @param proxyAddress The address of the proxy contract to be upgraded.
     * @param proxyAdminAddress The address of the proxy admin contract (optional, can be zero address).
     * @param newImplementationAddress The address of the new implementation contract.
     * @param contractInfo Contains the path to the contract artifact file.
     * @param opts Contains additional options, such as the upgrade approval process ID.
     *
     * @return inputs The array of strings representing the command to propose the upgrade.
     */
    function buildProposeUpgradeCommand(
        address proxyAddress,
        address proxyAdminAddress,
        address newImplementationAddress,
        ContractInfo memory contractInfo,
        Options memory opts
    ) internal view returns (string[] memory) {
        Vm vm = Vm(Utils.CHEATCODE_ADDRESS);

        string[] memory inputBuilder = new string[](255);
        uint256 i = 0;

        inputBuilder[i++] = "npx";
        inputBuilder[i++] = string(
            abi.encodePacked("@openzeppelin/defender-deploy-client-cli@", Versions.DEFENDER_DEPLOY_CLIENT_CLI)
        );
        inputBuilder[i++] = "propose";
        inputBuilder[i++] = "--proxyAddress";
        inputBuilder[i++] = vm.toString(proxyAddress);
        inputBuilder[i++] = "--newImplementationAddress";
        inputBuilder[i++] = vm.toString(newImplementationAddress);
        inputBuilder[i++] = "--chainId";
        inputBuilder[i++] = vm.toString(block.chainid);
        inputBuilder[i++] = "--artifactPath";
        inputBuilder[i++] = contractInfo.artifactPath;

        if (proxyAdminAddress != address(0)) {
            inputBuilder[i++] = "--proxyAdminAddress";
            inputBuilder[i++] = vm.toString(proxyAdminAddress);
        }

        if (bytes(opts.defender.upgradeApprovalProcessId).length > 0) {
            inputBuilder[i++] = "--approvalProcessId";
            inputBuilder[i++] = opts.defender.upgradeApprovalProcessId;
        }

        string[] memory inputs = new string[](i);
        for (uint256 j = 0; j < i; j++) {
            inputs[j] = inputBuilder[j];
        }

        return inputs;
    }

    /**
     * @notice Retrieves the approval process for a given command by executing a bash command and parsing the output.
     *
     * @param command The command to execute.
     * @return ApprovalProcessResponse The parsed approval process response.
     */
    function getApprovalProcess(string memory command) internal returns (ApprovalProcessResponse memory) {
