            return "GPL-2.0-or-later";
        } else if (licenseSlice.equals("GPL-3.0".toSlice())) {
            return "GPL-3.0";
        } else if (licenseSlice.equals("GPL-3.0-only".toSlice())) {
            return "GPL-3.0-only";
        } else if (licenseSlice.equals("GPL-3.0-or-later".toSlice())) {
            return "GPL-3.0-or-later";
        } else if (licenseSlice.equals("LGPL-2.1".toSlice())) {
            return "LGPL-2.1";
        } else if (licenseSlice.equals("LGPL-2.1-only".toSlice())) {
            return "LGPL-2.1-only";
        } else if (licenseSlice.equals("LGPL-2.1-or-later".toSlice())) {
            return "LGPL-2.1-or-later";
        } else if (licenseSlice.equals("LGPL-3.0".toSlice())) {
            return "LGPL-3.0";
        } else if (licenseSlice.equals("LGPL-3.0-only".toSlice())) {
            return "LGPL-3.0-only";
        } else if (licenseSlice.equals("LGPL-3.0-or-later".toSlice())) {
            return "LGPL-3.0-or-later";
        } else if (licenseSlice.equals("BSD-2-Clause".toSlice())) {
            return "BSD-2-Clause";
        } else if (licenseSlice.equals("BSD-3-Clause".toSlice())) {
            return "BSD-3-Clause";
        } else if (licenseSlice.equals("MPL-2.0".toSlice())) {
            return "MPL-2.0";
        } else if (licenseSlice.equals("BSL-1.1".toSlice())) {
            return "BSL-1.1";
        } else if (licenseSlice.equals("Unlicense".toSlice())) {
            return "Unlicense";
        } else if (licenseSlice.equals("CC0-1.0".toSlice())) {
            return "CC0-1.0";
        } else if (licenseSlice.equals("AGPL-3.0".toSlice())) {
            return "AGPL-3.0";
        } else if (licenseSlice.equals("AGPL-3.0-only".toSlice())) {
            return "AGPL-3.0-only";
        } else if (licenseSlice.equals("AGPL-3.0-or-later".toSlice())) {
