     * @return The parsed line or an empty string if not required.
     */
    function _parseLine(
        string memory expectedPrefix,
        string memory stdout,
        bool required
    ) private pure returns (string memory) {
        strings.slice memory outputSlice = stdout.toSlice();
        strings.slice memory prefixSlice = expectedPrefix.toSlice();

        if (outputSlice.contains(prefixSlice)) {
            strings.slice memory remaining = outputSlice.copy();
            remaining.split(prefixSlice);
            string memory afterPrefix = remaining.toString();
            strings.slice memory afterPrefixSlice = afterPrefix.toSlice();
            string memory result = afterPrefixSlice.split("\n".toSlice()).toString();
