            inputBuilder[i++] = "--approvalProcessId";
            inputBuilder[i++] = opts.defender.upgradeApprovalProcessId;
        }

        string[] memory inputs = new string[](i);
        for (uint256 j = 0; j < i; j++) {
            inputs[j] = inputBuilder[j];
        }

