     *
     * @param command The base command to be executed (e.g., "approval-process:get").
     * @return inputs An array of strings representing the full CLI command with arguments.
     */
    function buildGetApprovalProcessCommand(string memory command) internal view returns (string[] memory) {
        Vm vm = Vm(Utils.CHEATCODE_ADDRESS);

        string[] memory inputBuilder = new string[](255);
        uint256 i = 0;

        inputBuilder[i++] = "npx";
        inputBuilder[i++] = string(
            abi.encodePacked("@openzeppelin/defender-deploy-client-cli@", Versions.DEFENDER_DEPLOY_CLIENT_CLI)
        );
        inputBuilder[i++] = command;
        inputBuilder[i++] = "--chainId";
        inputBuilder[i++] = vm.toString(block.chainid);

        string[] memory inputs = new string[](i);
        for (uint256 j = 0; j < i; j++) {
            inputs[j] = inputBuilder[j];
        }

        return inputs;
    }

    /**
     * @dev Parses the deployed contract address from the deploy command output.
     */
    function _parseDeployedAddress(string memory stdout) private pure returns (address) {
        string memory addressStr = _parseLine("Contract deployed at address: ", stdout, true);
        return _parseAddress(addressStr);
    }

    /**
     * @dev Parses an address from a hex string (e.g., "0x1234...").
     */
    function _parseAddress(string memory str) private pure returns (address addr) {
        bytes memory strBytes = bytes(str);
        if (strBytes.length != 42) {
            revert("Invalid address length");
        }
        if (strBytes[0] != "0" || strBytes[1] != "x") {
            revert("Invalid address format");
        }

        uint256 result = 0;
        for (uint256 i = 2; i < 42; i++) {
            result <<= 4;
            uint8 digit = uint8(strBytes[i]);
            if (digit >= 48 && digit <= 57) {
                result |= (digit - 48);
            } else if (digit >= 65 && digit <= 70) {
                result |= (digit - 55);
            } else if (digit >= 97 && digit <= 102) {
                result |= (digit - 87);
            } else {
                revert("Invalid hex character in address");
            }
        }
        addr = address(uint160(result));
    }
