// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {Vm} from "forge-std/Vm.sol";
import {strings} from "solidity-stringutils/src/strings.sol";

import {Options, DefenderOptions} from "../Options.sol";
import {ProposeUpgradeResponse, ApprovalProcessResponse} from "../Defender.sol";
import {ContractInfo, Utils} from "./Utils.sol";
import {Versions} from "./Versions.sol";

/**
 * @dev Internal library for deploying contracts and proposing upgrades using OpenZeppelin Defender.
 */
library DefenderDeploy {
    using strings for *;

    /**
     * @notice Deploys a contract using the provided contract name, constructor data, and deployment options.
     *
     * @param contractName The name of the contract to be deployed.
     * @param constructorData The encoded constructor arguments for the contract.
     * @param defenderOpts The deployment options, including any specific configurations for the Defender service.
     *
     * @return The address of the deployed contract.
     */
    function deploy(
        string memory contractName,
        bytes memory constructorData,
        DefenderOptions memory defenderOpts
    ) internal returns (address) {
        string memory outDir = Utils.getOutDir();
        ContractInfo memory contractInfo = Utils.getContractInfo(contractName, outDir);
        string memory buildInfoFile = Utils.getBuildInfoFile(contractInfo.sourceCodeHash, contractName, outDir);

        string[] memory inputs = buildDeployCommand(contractInfo, buildInfoFile, constructorData, defenderOpts);
        Vm.FfiResult memory result = Utils.runAsBashCommand(inputs);

        if (result.exitCode != 0) {
            revert(
                string(
                    abi.encodePacked(
                        "Failed to deploy contract ",
                        contractName,
                        " using Defender: ",
                        string(result.stderr)
                    )
                )
            );
        }

        string memory stdout = string(result.stdout);
        return _parseDeployedAddress(stdout);
    }

    /**
     * @notice Constructs a deploy command for deploying a contract using OpenZeppelin Defender.
     *
     * @param contractInfo Contains details about the contract, such as its name, path, and license.
     * @param buildInfoFile The file containing build information for the contract.
     * @param constructorData Bytecode for the contract's constructor, if any.
     * @param defenderOpts Configuration options for the Defender deployment.
     *
     * @return inputs The array of strings representing the deploy command.
     */
    function buildDeployCommand(
        ContractInfo memory contractInfo,
        string memory buildInfoFile,
        bytes memory constructorData,
        DefenderOptions memory defenderOpts
    ) internal view returns (string[] memory) {
        Vm vm = Vm(Utils.CHEATCODE_ADDRESS);

        if (bytes(defenderOpts.licenseType).length > 0 && defenderOpts.skipVerifySourceCode) {
            revert("Cannot set licenseType when skipVerifySourceCode is true");
        }
        if (bytes(defenderOpts.licenseType).length > 0 && defenderOpts.skipLicenseType) {
            revert("Cannot set licenseType when skipLicenseType is true");
        }

        string[] memory inputBuilder = new string[](255);
        uint256 i = 0;

        inputBuilder[i++] = "npx";
        inputBuilder[i++] = string(
            abi.encodePacked("@openzeppelin/defender-deploy-client-cli@", Versions.DEFENDER_DEPLOY_CLIENT_CLI)
        );
        inputBuilder[i++] = "deploy";
        inputBuilder[i++] = "--contractName";
        inputBuilder[i++] = contractInfo.shortName;
        inputBuilder[i++] = "--contractPath";
        inputBuilder[i++] = contractInfo.contractPath;
        inputBuilder[i++] = "--chainId";
        inputBuilder[i++] = vm.toString(block.chainid);
        inputBuilder[i++] = "--buildInfoFile";
        inputBuilder[i++] = buildInfoFile;

        if (constructorData.length > 0) {
            inputBuilder[i++] = "--constructorBytecode";
            inputBuilder[i++] = vm.toString(constructorData);
        }

        if (!defenderOpts.skipVerifySourceCode) {
            if (defenderOpts.skipLicenseType) {
                inputBuilder[i++] = "--skipLicenseType";
            } else if (bytes(defenderOpts.licenseType).length > 0) {
                inputBuilder[i++] = "--licenseType";
                inputBuilder[i++] = defenderOpts.licenseType;
            } else {
                string memory licenseType = _toLicenseType(contractInfo);
                if (bytes(licenseType).length > 0) {
                    inputBuilder[i++] = "--licenseType";
                    inputBuilder[i++] = licenseType;
                }
            }
        } else {
            inputBuilder[i++] = "--skipVerifySourceCode";
        }

        if (bytes(defenderOpts.relayerId).length > 0) {
            inputBuilder[i++] = "--relayerId";
            inputBuilder[i++] = defenderOpts.relayerId;
        }

        if (defenderOpts.salt != bytes32(0)) {
            inputBuilder[i++] = "--salt";
            inputBuilder[i++] = vm.toString(defenderOpts.salt);
        }

        if (defenderOpts.txOverrides.gasLimit > 0) {
            inputBuilder[i++] = "--gasLimit";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.gasLimit);
        }

        if (defenderOpts.txOverrides.gasPrice > 0) {
            inputBuilder[i++] = "--gasPrice";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.gasPrice);
        }

        if (defenderOpts.txOverrides.maxFeePerGas > 0) {
            inputBuilder[i++] = "--maxFeePerGas";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.maxFeePerGas);
        }

        if (defenderOpts.txOverrides.maxPriorityFeePerGas > 0) {
            inputBuilder[i++] = "--maxPriorityFeePerGas";
            inputBuilder[i++] = vm.toString(defenderOpts.txOverrides.maxPriorityFeePerGas);
        }

        if (bytes(defenderOpts.metadata).length > 0) {
